<?php
namespace App\Domain\WorkProcesses; use App\Models\WorkProcess; final class WorkProcessDependencyInspector { public function inspect(WorkProcess $process):array{$navigation=$process->navigationItems()->where('is_active',true)->count();$homepage=$process->homepageSections()->where('is_enabled',true)->count();$relations=$process->relatedSolutions()->publiclyVisible()->count()+$process->relatedProducts()->publiclyVisible()->count()+$process->relatedIndustries()->publiclyVisible()->count()+$process->relatedPages()->publiclyVisible()->count();return ['navigation'=>$navigation,'homepage'=>$homepage,'relations'=>$relations,'children'=>$process->stages()->count(),'blocked'=>$navigation+$homepage+$relations>0];} }
